-- Forge v1.0 DDL baseline. Apply through migrations; no production DB is included.
PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
PRAGMA busy_timeout=5000;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL, checksum TEXT NOT NULL);
CREATE TABLE principals(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('owner','device','system','plugin')), display_name TEXT NOT NULL, revoked_at TEXT);
CREATE TABLE projects(id TEXT PRIMARY KEY, host_id TEXT NOT NULL, name TEXT NOT NULL, canonical_path TEXT NOT NULL UNIQUE, default_branch TEXT NOT NULL, trust_mode TEXT NOT NULL CHECK(trust_mode IN ('untrusted','trusted-local','native-sandbox')), revision INTEGER NOT NULL DEFAULT 1, archived_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE environments(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, config_json TEXT NOT NULL CHECK(json_valid(config_json)), revision INTEGER NOT NULL, UNIQUE(project_id,name));
CREATE TABLE command_presets(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), environment_id TEXT REFERENCES environments(id), name TEXT NOT NULL, executable TEXT NOT NULL, argv_json TEXT NOT NULL CHECK(json_valid(argv_json)), cwd_relative TEXT NOT NULL, env_refs_json TEXT NOT NULL CHECK(json_valid(env_refs_json)), timeout_seconds INTEGER NOT NULL CHECK(timeout_seconds>0), approval_hash TEXT NOT NULL, revision INTEGER NOT NULL);
CREATE TABLE conversations(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE messages(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), role TEXT NOT NULL CHECK(role IN ('user','assistant','system','tool')), content_json TEXT NOT NULL CHECK(json_valid(content_json)), created_at TEXT NOT NULL);
CREATE TABLE tasks(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','todo','active','awaiting_acceptance','done','cancelled','archived')), current_revision INTEGER NOT NULL, approved_revision INTEGER, priority TEXT NOT NULL CHECK(priority IN ('low','normal','high','urgent')), position INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE task_revisions(task_id TEXT NOT NULL REFERENCES tasks(id), revision INTEGER NOT NULL CHECK(revision>=1), contract_json TEXT NOT NULL CHECK(json_valid(contract_json)), content_hash TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES principals(id), created_at TEXT NOT NULL, PRIMARY KEY(task_id,revision));
CREATE TABLE workflow_revisions(id TEXT NOT NULL, revision INTEGER NOT NULL, name TEXT NOT NULL, definition_json TEXT NOT NULL CHECK(json_valid(definition_json)), content_hash TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','published','deprecated')), created_at TEXT NOT NULL, PRIMARY KEY(id,revision));
CREATE TABLE profile_revisions(id TEXT NOT NULL, revision INTEGER NOT NULL, profile_json TEXT NOT NULL CHECK(json_valid(profile_json)), content_hash TEXT NOT NULL, PRIMARY KEY(id,revision));
CREATE TABLE plugin_installations(id TEXT NOT NULL, version TEXT NOT NULL, manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)), digest TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('discovered','disabled','activating','ready','draining','failed','blocked','quarantined')), config_ref TEXT, PRIMARY KEY(id,version));
CREATE TABLE runs(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), contract_revision INTEGER NOT NULL, workflow_id TEXT NOT NULL, workflow_revision INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('queued','running','waiting_input','pausing','paused','canceling','succeeded','failed','cancelled','interrupted')), frozen_config_json TEXT NOT NULL CHECK(json_valid(frozen_config_json)), config_hash TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, finished_at TEXT, FOREIGN KEY(task_id,contract_revision) REFERENCES task_revisions(task_id,revision), FOREIGN KEY(workflow_id,workflow_revision) REFERENCES workflow_revisions(id,revision));
CREATE TABLE attempts(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), node_id TEXT NOT NULL, attempt_no INTEGER NOT NULL CHECK(attempt_no>=1), lease_epoch INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','running','waiting_approval','succeeded','failed','cancelled','interrupted')), executor_id TEXT, plugin_version TEXT, native_session_ref TEXT, process_identity_json TEXT CHECK(process_identity_json IS NULL OR json_valid(process_identity_json)), result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)), started_at TEXT, ended_at TEXT, UNIQUE(run_id,node_id,attempt_no));
CREATE TABLE workspaces(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), task_id TEXT NOT NULL REFERENCES tasks(id), canonical_path TEXT NOT NULL UNIQUE, branch TEXT NOT NULL, base_commit TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('ready','leased','quarantined','retained','removed')));
CREATE TABLE workspace_leases(id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), attempt_id TEXT REFERENCES attempts(id), epoch INTEGER NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('read','write')), state TEXT NOT NULL CHECK(state IN ('active','released','quarantined')), acquired_at TEXT NOT NULL, released_at TEXT);
CREATE UNIQUE INDEX ux_workspace_active_writer ON workspace_leases(workspace_id) WHERE mode='write' AND state IN ('active','quarantined');
CREATE TABLE code_snapshots(id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), run_id TEXT NOT NULL REFERENCES runs(id), commit_sha TEXT NOT NULL, tree_sha TEXT NOT NULL, base_sha TEXT NOT NULL, content_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE approvals(id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), task_id TEXT REFERENCES tasks(id), kind TEXT NOT NULL CHECK(kind IN ('task','permission','workflow','acceptance','merge','device')), expected_revision INTEGER NOT NULL, scope_hash TEXT NOT NULL, action_digest TEXT NOT NULL, snapshot_id TEXT REFERENCES code_snapshots(id), status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected','expired','superseded')), request_json TEXT NOT NULL CHECK(json_valid(request_json)), decided_by TEXT REFERENCES principals(id), decision_json TEXT CHECK(decision_json IS NULL OR json_valid(decision_json)), expires_at TEXT NOT NULL, decided_at TEXT);
CREATE TABLE artifacts(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), run_id TEXT REFERENCES runs(id), attempt_id TEXT REFERENCES attempts(id), snapshot_id TEXT REFERENCES code_snapshots(id), kind TEXT NOT NULL, relative_path TEXT NOT NULL, mime TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size>=0), content_hash TEXT NOT NULL, redaction_version TEXT NOT NULL, created_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE review_issues(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), snapshot_id TEXT NOT NULL REFERENCES code_snapshots(id), artifact_id TEXT NOT NULL REFERENCES artifacts(id), severity TEXT NOT NULL CHECK(severity IN ('blocking','advisory')), status TEXT NOT NULL CHECK(status IN ('open','resolved','waived','stale')), criterion_id TEXT, anchor_json TEXT NOT NULL CHECK(json_valid(anchor_json)), revision INTEGER NOT NULL);
CREATE TABLE verification_results(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), snapshot_id TEXT NOT NULL REFERENCES code_snapshots(id), criterion_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pass','fail','unverified','not_applicable','waived')), evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)), actor_id TEXT NOT NULL REFERENCES principals(id), artifact_id TEXT REFERENCES artifacts(id), created_at TEXT NOT NULL);
CREATE TABLE context_bundles(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), run_id TEXT REFERENCES runs(id), manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)), content_hash TEXT NOT NULL, token_estimate INTEGER, created_at TEXT NOT NULL);
CREATE TABLE knowledge_sources(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), source_uri TEXT NOT NULL, revision TEXT NOT NULL, content_hash TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','stale','revoked')), created_at TEXT NOT NULL, UNIQUE(project_id,source_uri,revision));
CREATE TABLE knowledge_chunks(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES knowledge_sources(id), project_id TEXT NOT NULL REFERENCES projects(id), start_line INTEGER, end_line INTEGER, text TEXT NOT NULL, search_tokens TEXT NOT NULL, metadata_json TEXT NOT NULL CHECK(json_valid(metadata_json)));
CREATE VIRTUAL TABLE knowledge_fts USING fts5(chunk_id UNINDEXED, project_id UNINDEXED, search_tokens, tokenize='unicode61');
CREATE TABLE memories(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), kind TEXT NOT NULL CHECK(kind IN ('project','experience')), status TEXT NOT NULL CHECK(status IN ('candidate','validated','stale','revoked')), content_json TEXT NOT NULL CHECK(json_valid(content_json)), source_refs_json TEXT NOT NULL CHECK(json_valid(source_refs_json)), revision INTEGER NOT NULL, expires_at TEXT, last_verified_at TEXT);
CREATE TABLE checkpoints(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), attempt_id TEXT REFERENCES attempts(id), state_json TEXT NOT NULL CHECK(json_valid(state_json)), created_at TEXT NOT NULL);
CREATE TABLE command_receipts(id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id), idempotency_key TEXT NOT NULL, payload_hash TEXT NOT NULL, method TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('accepted','completed','failed','unknown')), result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)), created_at TEXT NOT NULL, UNIQUE(principal_id,idempotency_key));
CREATE TABLE operations(id TEXT PRIMARY KEY, run_id TEXT REFERENCES runs(id), command_receipt_id TEXT REFERENCES command_receipts(id), kind TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('intent','executing','completed','failed','unknown')), precondition_json TEXT NOT NULL CHECK(json_valid(precondition_json)), result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)), created_at TEXT NOT NULL);
CREATE TABLE events(seq INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL UNIQUE, aggregate_id TEXT NOT NULL, aggregate_revision INTEGER NOT NULL, project_id TEXT REFERENCES projects(id), run_id TEXT REFERENCES runs(id), attempt_id TEXT REFERENCES attempts(id), event_type TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES principals(id), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), created_at TEXT NOT NULL);
CREATE INDEX ix_events_project_seq ON events(project_id,seq);
CREATE INDEX ix_tasks_project_state ON tasks(project_id,state,position);
CREATE INDEX ix_attempts_run_state ON attempts(run_id,state);
CREATE TABLE usage_records(id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempts(id), input_tokens INTEGER, output_tokens INTEGER, cost_minor INTEGER, currency TEXT, is_estimate INTEGER NOT NULL DEFAULT 0 CHECK(is_estimate IN (0,1)), provider_json TEXT CHECK(provider_json IS NULL OR json_valid(provider_json)));
CREATE TABLE devices(id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id), label TEXT NOT NULL, project_allowlist_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(project_allowlist_json)), scopes_json TEXT NOT NULL CHECK(json_valid(scopes_json)), status TEXT NOT NULL CHECK(status IN ('pending','active','revoked')), created_at TEXT NOT NULL, last_seen_at TEXT);
CREATE TABLE pairing_requests(id TEXT PRIMARY KEY, nonce_hash TEXT NOT NULL UNIQUE, claim_secret_hash TEXT UNIQUE, approved_by TEXT REFERENCES principals(id), requested_scopes_json TEXT CHECK(requested_scopes_json IS NULL OR json_valid(requested_scopes_json)), granted_scopes_json TEXT CHECK(granted_scopes_json IS NULL OR json_valid(granted_scopes_json)), session_delivered_at TEXT, status TEXT NOT NULL CHECK(status IN ('pending','claimed','approved','expired','rejected')), device_id TEXT REFERENCES devices(id), expires_at TEXT NOT NULL, consumed_at TEXT);
CREATE TABLE sessions(id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id), device_id TEXT REFERENCES devices(id), token_hash TEXT NOT NULL UNIQUE, csrf_hash TEXT NOT NULL, expires_at TEXT NOT NULL, refresh_expires_at TEXT NOT NULL, rotated_from TEXT, revoked_at TEXT);
CREATE TABLE plugin_data(namespace TEXT NOT NULL, project_id TEXT REFERENCES projects(id), item_key TEXT NOT NULL, schema_version INTEGER NOT NULL, value_json TEXT NOT NULL CHECK(json_valid(value_json)), PRIMARY KEY(namespace,item_key));
-- Sensitive secret bytes are not stored in these tables. Persist opaque references only.
